import React, { useState, useEffect } from "react";
import axios from "axios";

const ApplyInternship = () => {
  const [formData, setFormData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_number: "",
    education: "",
    internship_offers: "",
    resume: null,
  });

  const [internships, setInternships] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch internship offers on mount
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/VJISS/internship_offers_details")
      .then((response) => {
        setInternships(response.data);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching internship details:", error);
        setLoading(false);
      });
  }, []);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "resume") {
      setFormData({ ...formData, resume: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    Object.entries(formData).forEach(([key, value]) => data.append(key, value));

    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/VJISS/apply_internship",
        data,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      alert("Application submitted successfully!");
      console.log(response.data);

      // Reset form
      setFormData({
        first_name: "",
        last_name: "",
        email: "",
        phone_number: "",
        education: "",
        internship_offers: "",
        resume: null,
      });
    } catch (error) {
      console.error(error);
      alert("Failed to submit application ❌");
    }
  };

  return (
    <form onSubmit={handleSubmit} encType="multipart/form-data" className="max-w-md mx-auto p-6 bg-white shadow rounded space-y-4">
      <h2 className="text-2xl font-bold text-center mb-4">Apply for Internship</h2>

      <input
        type="text"
        name="first_name"
        placeholder="First Name"
        value={formData.first_name}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      />
      <input
        type="text"
        name="last_name"
        placeholder="Last Name"
        value={formData.last_name}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      />
      <input
        type="email"
        name="email"
        placeholder="Email"
        value={formData.email}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      />
      <input
        type="text"
        name="phone_number"
        placeholder="Phone Number"
        value={formData.phone_number}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      />

      <select
        name="education"
        value={formData.education}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      >
        <option value="">Select Education</option>
        <option value="Diploma">Diploma</option>
        <option value="UG">Under Graduate</option>
        <option value="PG">Post Graduate</option>
        <option value="PhD">PhD</option>
      </select>

      <select
        name="internship_offers"
        value={formData.internship_offers}
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      >
        <option value="">Select Internship Offer</option>
        {loading ? (
          <option value="">Loading internships...</option>
        ) : (
          internships.map((internship) => (
            <option key={internship.internship_id} value={internship.internship_id}>
              {internship.internship_name}
            </option>
          ))
        )}
      </select>

      <input
        type="file"
        name="resume"
        accept=".pdf,.doc,.docx"
        onChange={handleChange}
        required
        className="w-full p-2 border rounded"
      />

      <button type="submit" className="w-full py-2 bg-blue-600 text-white font-semibold rounded hover:bg-blue-700">
        Apply
      </button>
    </form>
  );
};

export default ApplyInternship;
